SELECT ,
       c.embedding <=> CAST(#{vector} AS vector) AS raw_score

WHERE c.snapshot_id = #{snapshotId}
ORDER BY raw_score ASC, 
LIMIT #{limit}

SELECT , 0.0::double precision AS raw_score
WHERE c.snapshot_id = #{snapshotId} AND c.topic_key IN #{topic}
AND (c.document_id, c.version, c.chunk_id) NOT IN
(#{key.document.documentId}, #{key.document.version}, #{key.chunkId})
ORDER BY c.topic_key COLLATE "C" ASC, LIMIT #{limit}
